      "2518"
    ]
  },
  {
    "statement": "Two studies in Spain and Botswana found that rehabilitated Iberian lynx and wild-born but captive-reared orphaned cheetahs and leopards that were provided with live natural prey in captivity survived for between at least three months and 19 months after release.",
    "citations": [
      "2518"
    ]
  },
  {
    "statement": "Two before-and-after studies in the USA and the UK found that activity levels and behavioural diversity increased in felids when the felids were presented with a lure or pulley system.",
    "citations": [
      "1927"
    ]
  },
  {
    "statement": "A replicated, before-and-after study in the USA found that pacing behaviour decreased and walking increased in cougars when the cougars were provided with a carcass on a bungee.",
    "citations": [
      "1927"
    ]
  }
